from game.lessons import unit as U

LESSONS = {
1: [
 U("Resumir varias filas", "Las tutorías tienen asistencias conocidas y una pendiente, empecemos mirando esos valores para poder comprobar a mano el resumen", "SELECT id, asistencia\nFROM tutorias\nORDER BY id;", "1 significa que asistió, 0 que no asistió\nNULL significa que todavía no sabemos"),
 U("Contar filas o datos conocidos", "Hay cuatro filas de tutorías pero solo tres asistencias conocidas, COUNT(*) cuenta las filas y COUNT(asistencia) ignora el NULL, contar asistencias conocidas no es contar quién asistió", "SELECT COUNT(*) AS filas,\n  COUNT(asistencia) AS conocidas\nFROM tutorias;", "Observa la diferencia entre las dos cantidades\nPara contar asistentes necesitas una condición", error="COUNT(asistencia) también cuenta los ceros, porque son datos conocidos"),
 U("Sumar, promediar y buscar extremos", "Los valores conocidos son 1, 0 y 1, la suma da 2 y el promedio es 2 dividido por 3, NULL no entra en el cálculo, MIN y MAX muestran los extremos conocidos", "SELECT SUM(asistencia), AVG(asistencia),\n  MIN(asistencia), MAX(asistencia)\nFROM tutorias;", "AVG no divide por las cuatro filas\nSi no hay valores conocidos, SUM y AVG devuelven NULL", check="¿Por qué el promedio no es 0,5?")],
2: [
 U("Separar categorías antes de resumir", "Queremos saber cuántas materias tienen cada cantidad de créditos, mira primero los créditos individuales, varias materias pueden compartir esa característica sin ser filas idénticas", "SELECT nombre, creditos\nFROM materias\nORDER BY creditos, nombre;", "Los registros originales conservan todos sus campos\nVamos a agrupar solo por creditos"),
 U("Una fila de resultado por categoría", "GROUP BY forma grupos con el mismo valor de créditos y COUNT cuenta las materias de cada grupo, el resultado tiene una fila por categoría, no una por materia", "SELECT creditos, COUNT(*) AS materias\nFROM materias\nGROUP BY creditos\nORDER BY creditos;", "GROUP BY no exige que las filas completas sean iguales\nSolo compara las expresiones de agrupación", error="SQLite permite columnas sin agrupar ni resumir, pero su valor puede no representar al grupo"),
 U("Otros resúmenes de cada grupo", "También podemos calcular el promedio de cupos dentro de cada grupo de créditos, AVG se aplica por separado a cada grupo, las materias almacenadas siguen siendo las mismas", "SELECT creditos, AVG(cupos) AS cupos_medios\nFROM materias\nGROUP BY creditos\nORDER BY creditos;", "Los datos originales no se reemplazan por el resumen", check="¿Qué cambiaría si agrupas por cupos en lugar de créditos?")],
3: [
 U("Filtrar filas antes de formar grupos", "Para analizar solo materias con plazas disponibles, quitamos primero las que tienen cero cupos y después contamos por créditos, WHERE trabaja sobre cada materia", "SELECT creditos, COUNT(*) AS cantidad\nFROM materias\nWHERE cupos > 0\nGROUP BY creditos;", "WHERE define qué filas entran al cálculo\nTodavía no estamos filtrando el tamaño del grupo"),
 U("Filtrar los resúmenes", "Ahora solo interesan categorías que conserven al menos dos materias disponibles, HAVING revisa el conteo ya calculado y descarta grupos que no alcanzan ese mínimo", "SELECT creditos, COUNT(*) AS cantidad\nFROM materias\nWHERE cupos > 0\nGROUP BY creditos\nHAVING COUNT(*) >= 2;", "WHERE filtra materias, HAVING filtra grupos\nLa función cuenta solo las filas que pasaron WHERE", error="WHERE COUNT(*) >= 2 intenta usar un resumen antes de formar los grupos", check="¿Qué cambia si quitas WHERE pero conservas HAVING?")],
4: [
 U("Relacionar dos listas", "Cada tutoría guarda el identificador de su estudiante, para conocer el nombre buscamos la persona cuyo id coincide con estudiante_id, no comparamos los nombres", "SELECT id, estudiante_id, tema\nFROM tutorias\nORDER BY id;", "estudiantes.id identifica una persona\ntutorias.estudiante_id señala esa persona\nUna clave foránea puede declarar esta relación"),
 U("Construir el cruce", "Usamos e y t como nombres cortos de las tablas, ON indica qué valores deben coincidir, cada tutoría produce una fila con el nombre de su estudiante", "SELECT e.id, e.nombre, t.id AS tutoria\nFROM estudiantes AS e\nINNER JOIN tutorias AS t\n  ON e.id = t.estudiante_id;", "INNER JOIN conserva coincidencias\nON expresa la condición, no exige una clave foránea declarada", error="Ignacio aparece dos veces porque tiene dos tutorías, no es un duplicado accidental"),
 U("Contar personas o coincidencias", "Si contamos las filas del cruce contamos tutorías, para contar personas diferentes usamos DISTINCT sobre su identificador, son preguntas distintas sobre el mismo resultado", "SELECT COUNT(*) AS tutorias,\n  COUNT(DISTINCT e.id) AS personas\nFROM estudiantes e JOIN tutorias t\n  ON e.id = t.estudiante_id;", "Una relación de uno a muchos puede repetir la fila izquierda", check="¿Por qué no basta COUNT(e.id) para contar personas distintas?")]
}
